import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../App';

const LANG_LIST = [
  { code: 'en', name: 'English',    native: 'English',    flag: '🇬🇧', region: 'Pan India',      greeting: 'Welcome Farmer!' },
  { code: 'hi', name: 'Hindi',      native: 'हिंदी',       flag: '🇮🇳', region: 'North India',    greeting: 'किसान भाई, स्वागत है!' },
  { code: 'mr', name: 'Marathi',    native: 'मराठी',       flag: '🌾', region: 'Maharashtra',    greeting: 'शेतकरी बंधू, स्वागत आहे!' },
  { code: 'pa', name: 'Punjabi',    native: 'ਪੰਜਾਬੀ',      flag: '🌻', region: 'Punjab',         greeting: 'ਕਿਸਾਨ ਵੀਰ, ਜੀ ਆਇਆਂ ਨੂੰ!' },
  { code: 'te', name: 'Telugu',     native: 'తెలుగు',      flag: '🌴', region: 'Andhra / Telangana', greeting: 'రైతు అన్నా, స్వాగతం!' },
  { code: 'bn', name: 'Bengali',    native: 'বাংলা',       flag: '🐯', region: 'West Bengal',    greeting: 'কৃষক ভাই, স্বাগতম!' },
  { code: 'gu', name: 'Gujarati',   native: 'ગુજરાતી',     flag: '🦁', region: 'Gujarat',        greeting: 'ખેડૂત ભાઈ, સ્વાગત છે!' },
  { code: 'ta', name: 'Tamil',      native: 'தமிழ்',       flag: '🌺', region: 'Tamil Nadu',     greeting: 'விவசாயி அண்ணா, வரவேற்கிறோம்!' },
  { code: 'kn', name: 'Kannada',    native: 'ಕನ್ನಡ',       flag: '🐘', region: 'Karnataka',      greeting: 'ರೈತ ಬಂಧು, ಸ್ವಾಗತ!' },
  { code: 'or', name: 'Odia',       native: 'ଓଡ଼ିଆ',       flag: '🌊', region: 'Odisha',         greeting: 'କୃଷକ ଭାଇ, ସ୍ୱାଗତ!' },
  { code: 'ur', name: 'Urdu',       native: 'اردو',        flag: '🌙', region: 'Pan India',      greeting: '!کسان بھائی، خوش آمدید' },
];

export default function LanguageSelectPage() {
  const { setLang } = useAuth();
  const navigate = useNavigate();
  const [selected, setSelected] = useState(null);
  const [confirming, setConfirming] = useState(false);

  const pick = (code) => setSelected(code);

  const confirm = () => {
    if (!selected) return;
    setConfirming(true);
    setLang(selected);
    setTimeout(() => navigate('/login'), 700);
  };

  const selectedLang = LANG_LIST.find(l => l.code === selected);

  return (
    <div className="min-h-screen bg-mesh flex flex-col items-center justify-center px-4 py-10 relative overflow-hidden">
      {/* Background orbs */}
      <div className="fixed top-0 left-0 w-96 h-96 bg-green-500/8 rounded-full blur-3xl pointer-events-none" />
      <div className="fixed bottom-0 right-0 w-96 h-96 bg-green-700/8 rounded-full blur-3xl pointer-events-none" />
      <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-green-900/5 rounded-full blur-3xl pointer-events-none" />

      {/* Header */}
      <div className="text-center mb-10 animate-fade-in relative z-10">
        <div className="inline-flex items-center gap-3 mb-5">
          <div className="w-14 h-14 rounded-2xl btn-primary flex items-center justify-center text-3xl ai-glow shadow-2xl shadow-green-900/50">🌿</div>
          <div className="text-left">
            <div className="font-display font-black text-3xl text-white">SmartSheti <span className="gradient-text">AI</span></div>
            <div className="text-green-400 text-xs tracking-widest font-medium">SMART FARMING PLATFORM</div>
          </div>
        </div>

        <h1 className="font-display font-bold text-2xl md:text-3xl text-white mb-2">
          Choose Your Language
        </h1>
        <p className="text-gray-400 text-sm max-w-sm mx-auto">
          Select your preferred language to get farming guidance, crop tips, and AI assistance in your mother tongue.
        </p>

        {/* Greeting preview */}
        {selectedLang && (
          <div className="mt-4 inline-flex items-center gap-2 glass-green px-5 py-2.5 rounded-full border border-green-700/40 animate-fade-in">
            <span className="text-xl">{selectedLang.flag}</span>
            <span className="text-green-300 font-medium text-sm">{selectedLang.greeting}</span>
          </div>
        )}
      </div>

      {/* Language Grid */}
      <div className="w-full max-w-3xl relative z-10 animate-slide-up">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 mb-6">
          {LANG_LIST.map((lang) => (
            <button
              key={lang.code}
              onClick={() => pick(lang.code)}
              className={`
                relative glass rounded-2xl p-4 text-center transition-all duration-200 border group
                ${selected === lang.code
                  ? 'border-green-400/70 bg-green-900/30 scale-105 shadow-lg shadow-green-900/40'
                  : 'border-green-900/30 hover:border-green-700/50 hover:bg-green-900/10 hover:scale-102'
                }
              `}
            >
              {/* Selected checkmark */}
              {selected === lang.code && (
                <div className="absolute top-2 right-2 w-5 h-5 rounded-full bg-green-500 flex items-center justify-center">
                  <span className="text-white text-xs font-bold">✓</span>
                </div>
              )}

              <div className="text-3xl mb-2">{lang.flag}</div>
              <div className={`font-display font-bold text-base mb-0.5 transition-colors ${selected === lang.code ? 'text-green-300' : 'text-white'}`}>
                {lang.native}
              </div>
              <div className="text-gray-500 text-xs">{lang.name}</div>
              <div className={`text-xs mt-1 transition-colors ${selected === lang.code ? 'text-green-500' : 'text-gray-700'}`}>
                {lang.region}
              </div>
            </button>
          ))}
        </div>

        {/* Confirm Button */}
        <div className="flex flex-col items-center gap-3">
          <button
            onClick={confirm}
            disabled={!selected || confirming}
            className={`
              w-full max-w-sm py-4 rounded-2xl font-bold text-base flex items-center justify-center gap-3 transition-all duration-300
              ${selected
                ? 'btn-primary text-white shadow-2xl shadow-green-900/50 hover:shadow-green-900/70'
                : 'glass border border-green-900/30 text-gray-600 cursor-not-allowed'
              }
              ${confirming ? 'opacity-70' : ''}
            `}
          >
            {confirming ? (
              <><span className="animate-spin text-xl">⟳</span> Setting up your experience...</>
            ) : selected ? (
              <><span className="text-xl">{selectedLang?.flag}</span> Continue in {selectedLang?.native} →</>
            ) : (
              <>Select a language to continue</>
            )}
          </button>

          <p className="text-gray-600 text-xs text-center">
            You can change your language anytime from the sidebar settings
          </p>
        </div>
      </div>

      {/* Bottom badge */}
      <div className="mt-10 relative z-10 flex items-center gap-2 text-gray-700 text-xs">
        <span className="w-1.5 h-1.5 rounded-full bg-green-700" />
        Supporting 11 Indian languages for every farmer
        <span className="w-1.5 h-1.5 rounded-full bg-green-700" />
      </div>
    </div>
  );
}
